def compatible(spark_type, contract):
    sql_type = contract["type"]
    expected = {
        "bigint":"bigint", "int":"int", "bit":"boolean",
        "date":"date", "datetime2":"timestamp", "varchar":"string",
    }
    if sql_type == "decimal":
        return spark_type == f'decimal({contract["precision"]},{contract["scale"]})'
    return spark_type == expected.get(sql_type)

results = []
for name, columns in WAREHOUSE_CONTRACTS.items():
    df = spark.read.format("delta").load(f"{ROOT}/{name}")
    actual_fields = df.schema.fields
    issues = []
    if len(actual_fields) != len(columns):
        issues.append({"kind":"COLUMN_COUNT", "expected":len(columns),"actual":len(actual_fields)})
    for i, c in enumerate(columns):
        if i >= len(actual_fields):
            issues.append({"kind":"MISSING_COLUMN","column":c["name"]})
            continue
        f = actual_fields[i]
        if f.name != c["name"]:
            issues.append({"kind":"COLUMN_ORDER_OR_NAME","position":i+1,"expected":c["name"],"actual":f.name})
        if not compatible(f.dataType.simpleString(),c):
            issues.append({"kind":"TYPE_MISMATCH","column":c["name"],"warehouse_type":c["type"],"silver_type":f.dataType.simpleString()})
    if issues:
        results.append({"table":name,"status":"FAILED_SCHEMA","issues":issues})
        print(json.dumps(results[-1]))
        continue
    checks = [F.count(F.lit(1)).alias("_rows")]
    for c in columns:
        col = F.col("`" + c["name"].replace("`","``") + "`")
        if c["required"]:
            checks.append(F.sum(F.when(col.isNull(),1).otherwise(0)).alias("null_"+c["name"]))
        if c["type"] == "varchar":
            # Warehouse VARCHAR length is a byte limit. Synthetic data is expected ASCII;
            # octet_length checks encoded UTF-8 bytes conservatively.
            checks.append(F.sum(F.when(F.octet_length(col)>c["length"],1).otherwise(0)).alias("long_"+c["name"]))
    metrics = df.agg(*checks).first().asDict()
    for c in columns:
        null_count = metrics.get("null_"+c["name"],0) or 0
        long_count = metrics.get("long_"+c["name"],0) or 0
        if null_count:
            issues.append({"kind":"REQUIRED_NULL","column":c["name"],"rows":null_count})
        if long_count:
            issues.append({"kind":"VARCHAR_TOO_LONG","column":c["name"],"rows":long_count,"max_bytes":c["length"]})
    if metrics["_rows"] != EXPECTED_ROWS[name]:
        issues.append({"kind":"ROW_COUNT","expected":EXPECTED_ROWS[name],"actual":metrics["_rows"]})
    record = {"table":name,"rows":metrics["_rows"],"columns":len(columns),"status":"PASSED" if not issues else "FAILED","issues":issues}
    results.append(record)
    print(json.dumps(record))

summary = {
    "gate":"7A", "stage":"FINAL_SILVER_WAREHOUSE_COMPATIBILITY",
    "mode":"READ_ONLY", "tables_checked":len(results),
    "columns_checked":sum(r.get("columns",0) for r in results),
    "rows_checked":sum(r.get("rows",0) for r in results),
    "tables_failed":sum(r["status"]!="PASSED" for r in results),
    "status":"PASSED" if len(results)==17 and all(r["status"]=="PASSED" for r in results) else "FAILED"
}
print("GATE 7A FINAL COMPATIBILITY SUMMARY")
print(json.dumps(summary,indent=2))
if summary["status"] != "PASSED":
    raise RuntimeError("Gate 7A compatibility check FAILED; do not load Gold.")


